import GlobalStyle from './styles/GlobalStyle';
import ToDoList from './Components/ToDoList';
import RecoilStorageSync from './RecoilStorageSync';
import styled from 'styled-components';
import { useRecoilState } from 'recoil';
import { isDarkState } from './atoms/themeAtom';

const ThemeButton = styled.button`
	background-color: ${({ theme }) => theme.textColors.normal};
	width: 40px;
	height: 40px;
	border-radius: 18px;
`;

export const MaterialSymbol = styled.span`
  font-family: 'Material Symbols Outlined';
  font-weight: normal;
  font-style: normal;
  font-size: 24px;
  display: inline-block;
  vertical-align: middle;
  line-height: 1;
  color: ${({ theme }) => theme.textColors.reversed};

  font-variation-settings: 
    'FILL' 1,
    'wght' 400,
    'GRAD' 0,
    'opsz' 24;
`;


function App() {
	const [isDark, setIsDark] = useRecoilState(isDarkState);
	const toggleTheme = () => {
		console.log(isDark)
		setIsDark((prev) => !prev)
	}

  return (
		<>
			<ThemeProvider theme={() => useRecoilValue(isDarkState) ? darkTheme : lightTheme}>
				<GlobalStyle/>
				<RecoilStorageSync/>
				<ToDoList/>
				<ThemeButton onClick={toggleTheme}>
					<MaterialSymbol>{isDark ? "dark_mode" : "light_mode"}</MaterialSymbol>
				</ThemeButton>
			</ThemeProvider>
		</>
	);
}

export default App;
